<div class="mx-auto max-w-4xl space-y-6"><div class="page-heading"><div><p class="eyebrow">Employee services / Leave</p><h1>{{ $leave->user?->name }}</h1><p>{{ $leave->type->getLabel() }} · {{ $leave->start_date->format('d M') }} – {{ $leave->end_date->format('d M Y') }}</p></div><span class="status-badge">{{ $leave->status->getLabel() }}</span></div><section class="panel p-6"><dl class="grid gap-6 md:grid-cols-3"><div><dt class="text-sm text-slate-500">Duration</dt><dd class="font-semibold">{{ $leave->duration_in_days }} days</dd></div><div><dt class="text-sm text-slate-500">Hours</dt><dd>{{ $leave->hours ?: 'Full day(s)' }}</dd></div><div><dt class="text-sm text-slate-500">Reviewed by</dt><dd>{{ $leave->approver?->name ?: 'Pending' }}</dd></div><div class="md:col-span-3"><dt class="text-sm text-slate-500">Reason</dt><dd>{{ $leave->description }}</dd></div>@if($leave->rejection_reason)<div class="md:col-span-3"><dt class="text-sm text-rose-500">Rejection reason</dt><dd>{{ $leave->rejection_reason }}</dd></div>@endif</dl></section>@if((auth()->user()->isHR()||auth()->user()->isAdmin())&&$leave->isPending())<section class="panel p-6"><h2 class="font-bold">Review request</h2><textarea wire:model="rejection_reason" rows="3" class="form-input mt-4" placeholder="Reason required when rejecting"></textarea>@error('rejection_reason')<p class="form-error">{{ $message }}</p>@enderror<div class="mt-4 flex justify-end gap-3"><button wire:click="reject" class="btn-secondary">Reject</button><button wire:click="approve" wire:confirm="Approve this leave request?" class="btn-primary">Approve</button></div></section>@endif</div>
